// Diagnostic environment adapter only. Repository tests are unchanged.
import path from 'node:path';
import {pathToFileURL} from 'node:url';
const originalModule=path.resolve(path.dirname(process.execPath),'../node_modules/playwright/index.mjs');
const {chromium:original}=await import(pathToFileURL(originalModule).href);
export const chromium=new Proxy(original,{
 get(target,key){
  if(key==='launch')return(options={})=>target.launch({...options,executablePath:'/usr/bin/chromium',args:[...(options.args||[]),'--no-sandbox','--enable-unsafe-swiftshader']});
  const value=Reflect.get(target,key,target);return typeof value==='function'?value.bind(target):value;
 }
});
